#[test]
fn complete_array_trade() {
    for (path, result) in
        paths::<CryptocomTrade>(r###"[-0.0,17.5,31.5,2.5,"BUY","CryptocomTrade:0:i",-13.5]"###)
            .into_iter()
            .enumerate()
    {
        assert!(
            result.is_err(),
            "complete positional array accepted for CryptocomTrade path {path}"
        );
    }
}
